516		if _, err := s1.RegisterPatient(doc, "旧句柄患者"); !errors.Is(err, ErrClosed) {
517			t.Fatalf("old handle method err = %v, want ErrClosed", err)
518		}
519		if err := s1.Close(); !errors.Is(err, ErrClosed) {
520			t.Fatalf("old handle Close err = %v, want ErrClosed", err)
521		}
522	
523		// 新句柄正常工作，证明目录占用已随 Close 转移，而非旧句柄复活。
524		if _, err := s2.RegisterPatient(doc, "新句柄患者"); err != nil {
525			t.Fatalf("new store should work: %v", err)
526		}
527	}
528

